const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:12px;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font-size:13px;line-height:1.4}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:8px;gap:5px}\nbutton,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\nbutton:disabled{opacity:.55;cursor:default}\nbutton:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n[hidden]{display:none!important}\n\n.bar{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.tabs{flex:1;min-width:0;display:flex;gap:4px}\n.tab{flex:none;display:inline-flex;align-items:center;gap:4px;min-height:28px;padding:2px 10px;border:1px solid transparent;border-radius:999px;background:transparent;color:var(--muted);font-size:13px;white-space:nowrap}\n.tab.on{background:var(--soft);color:var(--ink);font-weight:600}\n.tab .n{font-variant-numeric:tabular-nums;font-size:12px}\n.tab.hot .n{color:var(--accent);font-weight:700}\n.add{flex:none;width:30px;height:30px;padding:0;border:none;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:20px;line-height:1}\n.prog{flex:none;height:3px;border-radius:2px;background:var(--line);overflow:hidden}\n.prog i{display:block;height:100%;background:var(--accent);transition:width .3s}\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column}\n\n.btn{min-height:32px;padding:5px 14px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn.small{min-height:26px;padding:2px 9px;border-radius:999px;font-size:12px;flex:none}\n\n.review{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.faces{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.face{flex:1 1 0;min-height:0;min-width:0;display:flex;flex-direction:column;gap:2px;padding:7px 10px;border:1px solid var(--line);border-radius:12px;background:var(--panel-paper)}\n.face.tap{cursor:pointer}\n.face.a{border-color:var(--accent);animation:fcrise .22s ease-out}\n@keyframes fcrise{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.face.a{animation:none}}\n.fh{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.lbl{font-size:11px;letter-spacing:.08em;color:var(--muted)}\n.chip{font-size:11px;padding:0 7px;border-radius:999px;background:var(--soft);color:var(--ink);white-space:nowrap}\n.txt{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;font-size:15px;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}\n.txt span{margin:auto 0}\n.acts{flex:none;display:flex;gap:6px}\n.flipbtn{flex:1;min-height:38px;font-size:14px}\n.rate{flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;min-height:40px;padding:3px 2px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);line-height:1.25}\n.rate b{font-size:13px;white-space:nowrap}\n.rate small{font-size:11px;white-space:nowrap}\n.rate.good{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.rate.hard{background:var(--soft);border-color:var(--accent)}\n.err{flex:none;font-weight:600;font-size:12px}\n\n.empty{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;text-align:center;padding:4px}\n.mark{width:34px;height:34px;border-radius:50%;background:var(--soft);color:var(--accent);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700;flex:none}\n.et{font-size:15px;font-weight:700}\n.ep{margin:0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}\n.eb{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-top:2px}\n\n.list{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:5px;padding-right:2px}\n.row{flex:none;display:flex;flex-direction:column;gap:1px;width:100%;text-align:left;padding:6px 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink)}\n.rq{min-width:0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere}\n.rm{font-size:11px;color:var(--muted)}\n.row.due .rm{color:var(--accent);font-weight:700}\n.rules{flex:none;margin-top:4px;padding:8px 10px;border-radius:10px;background:var(--soft);font-size:12px;line-height:1.5;color:var(--ink)}\n.rt{font-weight:700;margin-bottom:2px}\n\n.ed{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.edhead{flex:none;display:flex;align-items:center;gap:8px;min-width:0}\n.edt{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.fld{flex:1 1 0;min-height:0;display:flex;flex-direction:column;gap:2px}\n.fl{flex:none;font-size:11px;color:var(--muted)}\n.ta{flex:1;min-height:0;width:100%;resize:none;padding:6px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);line-height:1.4}\n.ta::placeholder{color:var(--muted)}\n.info{flex:none;font-size:12px;color:var(--muted)}\n.info.warn{color:var(--ink);font-weight:600}\n.note{flex:none;font-size:12px;font-weight:600;color:var(--accent)}\n.edacts .btn{flex:1}\n.edacts .btn.primary{flex:2}\n\n.card[data-size=\"3x3\"] .fl{display:none}\n.card[data-size=\"3x3\"] .info:not(.warn),.card[data-size=\"6x3\"] .info:not(.warn){display:none}\n.card[data-size=\"3x3\"] .txt{font-size:14px}\n.card[data-size=\"3x3\"] .face{padding:5px 8px}\n.card[data-size=\"3x3\"] .faces.flipped .face.q{flex:none;max-height:46px}\n.card[data-size=\"3x3\"] .faces.flipped .face.q .fh{display:none}\n.card[data-size=\"3x3\"] .faces.flipped .face.q .txt{font-size:12px;color:var(--muted)}\n.card[data-size=\"3x3\"] .rate b{font-size:12px}\n.card[data-size=\"3x3\"] .rate small{font-size:10px}\n.card[data-size=\"3x3\"] .tab{padding:2px 8px}\n.card[data-size=\"3x3\"] .ep{font-size:11px}\n.card[data-size=\"3x3\"] .eb .btn{min-height:30px;padding:4px 10px}\n\n.card[data-size=\"6x3\"] .faces.flipped{flex-direction:row}\n.card[data-size=\"6x3\"] .txt{font-size:14px}\n\n.card[data-size=\"3x6\"] .txt{font-size:16px}\n.card[data-size=\"3x6\"] .faces.flipped .face{flex:1 1 0}\n\n.card[data-size=\"6x6\"] .txt{font-size:19px}\n.card[data-size=\"6x6\"] .face{padding:10px 14px}\n.card[data-size=\"6x6\"] .rate{min-height:50px}\n.card[data-size=\"6x6\"] .rate b{font-size:15px}\n.card[data-size=\"6x6\"] .flipbtn{min-height:46px;font-size:16px}\n.card[data-size=\"6x6\"] .tab{font-size:14px}\n\n.card[data-size=\"6x3\"] .row,.card[data-size=\"6x6\"] .row{flex-direction:row;align-items:center;gap:10px}\n.card[data-size=\"6x3\"] .rq,.card[data-size=\"6x6\"] .rq{flex:1}\n.card[data-size=\"6x3\"] .rm,.card[data-size=\"6x6\"] .rm{flex:none;white-space:nowrap}\n.card[data-size=\"6x3\"] .ed,.card[data-size=\"6x6\"] .ed{gap:8px}\n.card[data-size=\"6x3\"] .ed{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto 1fr auto;column-gap:8px;row-gap:6px}\n.card[data-size=\"6x3\"] .ed .edhead{grid-column:1 / 3}\n.card[data-size=\"6x3\"] .ed .fld{grid-row:2;min-width:0}\n.card[data-size=\"6x3\"] .ed .note,.card[data-size=\"6x3\"] .ed .err,.card[data-size=\"6x3\"] .ed .acts{grid-column:1 / 3}\n";
var FC_STEPS=[1,3,7,14,30,60];
function fcPad(n){return String(n).padStart(2,'0');}
function fcYmd(t){return t.getFullYear()+'-'+fcPad(t.getMonth()+1)+'-'+fcPad(t.getDate());}
function fcParse(d){var p=String(d).split('-').map(Number);return new Date(p[0],p[1]-1,p[2]);}
function fcAddDays(d,n){var t=fcParse(d);t.setDate(t.getDate()+n);return fcYmd(t);}
function fcDiff(a,b){return Math.round((fcParse(b)-fcParse(a))/86400000);}
function fcPlan(box,grade){
  var b=box||0;
  if(grade==='good'){var nb=Math.min(b+1,FC_STEPS.length-1);return {box:nb,days:FC_STEPS[nb]};}
  if(grade==='hard'){return {box:b,days:2};}
  return {box:0,days:1};
}
function fcDays(n){return n===1?'明天':n+'天后';}
function fcDue(due,today){
  var n=fcDiff(today,due);
  if(n<0)return '逾期'+(-n)+'天';
  if(n===0)return '今天';
  if(n===1)return '明天';
  return due.slice(5)+'（'+n+'天后）';
}
function fcList(s){return Array.isArray(s.cards)?s.cards:[];}
function fcErr(e){return (e&&e.message)?e.message:'保存失败，请重试';}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,percent}=ctx;
  const today=day();
  const cards=fcList(state);
  const byDue=(a,b)=>a.due<b.due?-1:(a.due>b.due?1:0);
  const due=cards.filter(c=>c.due<=today).sort(byDue);
  const doneToday=cards.filter(c=>c.last===today).length;
  const tab=ui.tab==='all'?'all':'review';
  const flipId=ui.flip||null;

  function go(patch){Object.assign(ui,patch);redraw();}
  function nextUi(patch){return Object.assign({},ui,patch);}
  function fail(e){ui.busy=false;ui.err=fcErr(e);redraw();}
  function settle(p){
    return p.then(ok=>{if(ok===false){ui.busy=false;ui.err='保存没有成功，请重试';redraw();}}).catch(fail);
  }
  function btn(label,onClick,cls,disabled){
    return el('button',{class:'btn '+(cls||''),type:'button',disabled:!!disabled,onclick:onClick},label);
  }

  function flip(c){ui.flip=c.id;redraw();}
  function rate(c,grade){
    if(ui.busy)return;
    ui.busy=true;ui.err='';
    const t=day();
    settle(commit(s=>Object.assign({},s,{cards:fcList(s).map(x=>{
      if(x.id!==c.id||x.due>t)return x;
      const p=fcPlan(x.box,grade);
      return Object.assign({},x,{box:p.box,due:fcAddDays(t,p.days),last:t,reps:(x.reps||0)+1,lapses:(x.lapses||0)+(grade==='again'?1:0)});
    })}),nextUi({busy:false,flip:null,err:''})));
  }

  function openEdit(id){
    const c=id?cards.find(x=>x.id===id):null;
    go({view:'edit',editId:c?c.id:null,draft:{q:c?c.q:'',a:c?c.a:''},err:'',notice:'',confirmDel:false,added:0,busy:false});
  }
  function closeEdit(){
    go({view:'main',editId:null,draft:null,err:'',notice:'',confirmDel:false,added:0,busy:false});
  }
  function save(){
    if(ui.busy)return;
    const d=ui.draft||{q:'',a:''};
    const q=(d.q||'').trim(),a=(d.a||'').trim();
    if(!q||!a){ui.err=!q?'请先写问题':'请先写答案';redraw();return;}
    ui.busy=true;ui.err='';
    const id=ui.editId;
    if(id){
      settle(commit(s=>Object.assign({},s,{cards:fcList(s).map(x=>x.id===id?Object.assign({},x,{q:q,a:a}):x)}),
        nextUi({view:'main',editId:null,draft:null,busy:false,err:'',notice:'',confirmDel:false,added:0})));
    }else{
      const nid=uid(),t=day();
      settle(commit(s=>{
        const list=fcList(s);
        if(list.some(x=>x.id===nid))return s;
        return Object.assign({},s,{cards:list.concat([{id:nid,q:q,a:a,created:t,due:t,box:0,last:'',reps:0,lapses:0}])});
      },nextUi({busy:false,err:'',draft:{q:'',a:''},notice:'已添加，可以接着写下一张',added:(ui.added||0)+1})));
    }
  }
  function remove(c){
    if(ui.busy)return;
    ui.busy=true;
    settle(commit(s=>Object.assign({},s,{cards:fcList(s).filter(x=>x.id!==c.id)}),
      nextUi({view:'main',editId:null,draft:null,busy:false,err:'',notice:'',confirmDel:false,added:0,flip:ui.flip===c.id?null:ui.flip})));
  }


  function empty(title,text,btns,mark){
    const kids=[
      mark?el('div',{class:'mark','aria-hidden':'true'},mark):null,
      el('div',{class:'et'},title),
      text?el('p',{class:'ep'},text):null,
      el('div',{class:'eb'},...btns)
    ].filter(Boolean);
    return el('div',{class:'empty'},...kids);
  }

  function chipText(c){
    if(!c.reps)return '新卡';
    if(c.due<today)return '逾期'+fcDiff(c.due,today)+'天';
    return '第'+(c.reps+1)+'次复习';
  }

  function rateBtn(c,grade,label){
    const days=fcPlan(c.box,grade).days;
    return el('button',{class:'rate '+grade,type:'button',disabled:!!ui.busy,title:label+'：'+fcDays(days)+'再看',onclick:()=>rate(c,grade)},
      el('b',{},label),el('small',{},fcDays(days)));
  }

  function renderDone(){
    const future=cards.filter(c=>c.due>today).sort(byDue);
    let next='';
    if(future.length){
      const d=future[0].due;
      const n=future.filter(c=>c.due===d).length;
      next='下一批：'+fcDue(d,today)+'，'+n+' 张';
    }
    const head=doneToday?'今天的复习完成了':'今天没有要复习的';
    const text=doneToday?('今天复习了 '+doneToday+' 张。'+next):next;
    return empty(head,text,[btn('添加卡片',()=>openEdit(null),'ghost')],'✓');
  }

  function renderReview(){
    if(!cards.length){
      return empty('还没有卡片','自己写问题和答案，先看题，再翻答案。',[btn('添加第一张卡片',()=>openEdit(null),'primary')]);
    }
    if(!due.length)return renderDone();
    const c=due[0];
    const flipped=flipId===c.id;
    const qAttrs={class:'face q'+(flipped?'':' tap')};
    if(!flipped)qAttrs.onclick=()=>flip(c);
    const q=el('div',qAttrs,
      el('div',{class:'fh'},el('span',{class:'lbl'},'问题'),el('span',{class:'chip'},chipText(c))),
      el('div',{class:'txt'},el('span',{},c.q)));
    const faces=[q];
    if(flipped){
      faces.push(el('div',{class:'face a'},
        el('div',{class:'fh'},el('span',{class:'lbl'},'答案')),
        el('div',{class:'txt'},el('span',{},c.a))));
    }
    const acts=flipped
      ?el('div',{class:'acts rates'},rateBtn(c,'good','记住了'),rateBtn(c,'hard','勉强记得'),rateBtn(c,'again','忘了'))
      :el('div',{class:'acts'},btn('翻开答案',()=>flip(c),'primary flipbtn'));
    const kids=[el('div',{class:'faces'+(flipped?' flipped':'')},...faces)];
    if(ui.err)kids.push(el('div',{class:'err',role:'alert'},'⚠ '+ui.err));
    kids.push(acts);
    return el('div',{class:'review'},...kids);
  }

  function renderAll(){
    if(!cards.length){
      return empty('还没有卡片','添加后会出现在这里，到期的排在最前。',[btn('添加卡片',()=>openEdit(null),'primary')]);
    }
    const rows=cards.slice().sort(byDue).map(c=>{
      const isDue=c.due<=today;
      const meta=!c.reps?(isDue?'新卡 · 今天复习':'新卡'):(isDue?(c.due<today?fcDue(c.due,today)+' · 待复习':'今天复习'):'下次 '+fcDue(c.due,today));
      return el('button',{class:'row'+(isDue?' due':''),type:'button',title:c.q,onclick:()=>openEdit(c.id)},
        el('span',{class:'rq'},c.q),el('span',{class:'rm'},meta));
    });
    const rules=el('div',{class:'rules'},
      el('div',{class:'rt'},'复习安排'),
      el('div',{},'记住了：升一档，依次隔 3 / 7 / 14 / 30 / 60 天再看'),
      el('div',{},'勉强记得：档位不变，2 天后再看'),
      el('div',{},'忘了：退回起点，明天再看'),
      el('div',{},'新卡片添加当天就会出现在复习里'));
    return el('div',{class:'list'},...rows,rules);
  }

  function tabBtn(key,label,n){
    const on=tab===key;
    const cls='tab'+(on?' on':'')+(key==='review'&&n>0?' hot':'');
    return el('button',{class:cls,type:'button',role:'tab','aria-selected':on?'true':'false',onclick:()=>go({tab:key})},
      label,el('span',{class:'n'},String(n)));
  }

  function renderMain(){
    const bar=el('div',{class:'bar'},
      el('div',{class:'tabs',role:'tablist'},tabBtn('review','复习',due.length),tabBtn('all','全部',cards.length)),
      el('button',{class:'add',type:'button','aria-label':'添加卡片',title:'添加卡片',onclick:()=>openEdit(null)},'+'));
    const out=[bar];
    const total=doneToday+due.length;
    if(tab==='review'&&total>0){
      const fill=el('i',{});
      fill.style.width=percent(doneToday,total)+'%';
      out.push(el('div',{class:'prog','aria-hidden':'true'},fill));
    }
    out.push(el('div',{class:'body'},tab==='all'?renderAll():renderReview()));
    return out;
  }


  function renderEditor(){
    const editing=ui.editId?cards.find(x=>x.id===ui.editId):null;
    if(ui.editId&&!editing){ui.view='main';ui.editId=null;return renderMain();}
    if(!ui.draft)ui.draft={q:'',a:''};
    const d=ui.draft;
    const note=el('div',{class:'note',role:'status'},'✓ '+(ui.notice||''));
    note.hidden=!ui.notice;
    const field=(key,label,ph)=>{
      const ta=el('textarea',{class:'ta','aria-label':label,placeholder:ph,maxlength:'2000',
        oninput:ev=>{d[key]=ev.target.value;if(ui.notice){ui.notice='';note.hidden=true;}}});
      ta.value=d[key]||'';
      return el('label',{class:'fld'},el('span',{class:'fl'},label),ta);
    };
    const confirming=!!(ui.confirmDel&&editing);
    const acts=confirming
      ?[btn('确认删除',()=>remove(editing),'primary',ui.busy),btn('取消',()=>go({confirmDel:false}),'ghost')]
      :[btn(editing?'保存修改':'保存卡片',save,'primary',ui.busy)].concat(editing?[btn('删除',()=>go({confirmDel:true,err:''}),'ghost')]:[]);
    const kids=[
      el('div',{class:'edhead'},
        btn(ui.added?'完成':'‹ 返回',closeEdit,'ghost small'),
        el('div',{class:'edt'},editing?'编辑卡片':'添加卡片')),
      field('q','问题','问题，例如：光合作用的场所是？'),
      field('a','答案','答案')
    ];
    if(editing){
      kids.push(el('div',{class:'info'+(confirming?' warn':'')},confirming?'删除后无法恢复。':(editing.reps?('已复习 '+editing.reps+' 次 · 下次 '+fcDue(editing.due,today)):'新卡 · 今天开始复习')));
    }
    kids.push(note);
    if(ui.err)kids.push(el('div',{class:'err',role:'alert'},'⚠ '+ui.err));
    kids.push(el('div',{class:'acts edacts'},...acts));
    return [el('div',{class:'ed'},...kids)];
  }

  root.append(...(ui.view==='edit'?renderEditor():renderMain()));
